<?php
declare(strict_types=1);
namespace Gda\AdminGlobal\Repositories;
use PDO;

final class GlobalAdministrationRepository{
 public function __construct(private PDO $db){}
 public function dashboard():array{return[
  'companies'=>(int)$this->db->query('SELECT COUNT(*) FROM companies')->fetchColumn(),'active_companies'=>(int)$this->db->query("SELECT COUNT(*) FROM companies WHERE status='active'")->fetchColumn(),'inactive_companies'=>(int)$this->db->query("SELECT COUNT(*) FROM companies WHERE status='inactive'")->fetchColumn(),'cycles'=>(int)$this->db->query('SELECT COUNT(*) FROM cycles')->fetchColumn(),'active_cycles'=>(int)$this->db->query("SELECT COUNT(*) FROM cycles WHERE status='active'")->fetchColumn(),'participants'=>(int)$this->db->query('SELECT COUNT(*) FROM participants')->fetchColumn(),'contributions'=>(int)$this->db->query('SELECT COUNT(*) FROM contributions')->fetchColumn(),'receipts'=>(int)$this->db->query('SELECT COUNT(*) FROM payment_receipts')->fetchColumn()];}
 public function companies():array{return$this->db->query("SELECT c.*,u.name admin_name,(SELECT COUNT(*) FROM cycles cy WHERE cy.company_id=c.id)cycle_count,(SELECT COUNT(*) FROM participants p WHERE p.company_id=c.id)participant_count,(SELECT MAX(m.last_seen) FROM mobile_access_logs m WHERE m.company_id=c.id)last_activity FROM companies c LEFT JOIN users u ON u.id=(SELECT u2.id FROM users u2 WHERE u2.company_id=c.id AND u2.role='client_admin' ORDER BY u2.id LIMIT 1) ORDER BY c.name")->fetchAll();}
 public function company(int $id):?array{$s=$this->db->prepare('SELECT * FROM companies WHERE id=?');$s->execute([$id]);$company=$s->fetch();if(!$company)return null;$queries=['users'=>'SELECT id,name,email,role,active,created_at FROM users WHERE company_id=? ORDER BY id','cycles'=>'SELECT * FROM cycles WHERE company_id=? ORDER BY id DESC','participants'=>'SELECT id,name,phone,active,created_at FROM participants WHERE company_id=? ORDER BY name','settings'=>'SELECT setting_key,setting_value,updated_at FROM app_settings WHERE company_id=? ORDER BY setting_key','activity'=>'SELECT * FROM mobile_access_logs WHERE company_id=? ORDER BY last_seen DESC LIMIT 20','errors'=>"SELECT action,metadata,created_at FROM global_audit_logs WHERE target_type='company' AND target_id=CAST(? AS CHAR) AND action LIKE '%failed%' ORDER BY id DESC LIMIT 20",'migration_history'=>'SELECT migration,event,created_at FROM tenant_migration_log WHERE company_id=? ORDER BY id DESC'];foreach($queries as$key=>$sql){$q=$this->db->prepare($sql);$q->execute([$id]);$company[$key]=$q->fetchAll();}$company['environment_status']=$company['status']==='active'&&!empty($company['users'])?'operational':'attention';return$company;}
 public function cycles():array{return$this->db->query("SELECT cy.*,c.name company_name,(SELECT COUNT(*) FROM cycle_participants cp WHERE cp.cycle_id=cy.id)participant_count,(SELECT MAX(created_at) FROM contributions co WHERE co.cycle_id=cy.id)last_activity FROM cycles cy JOIN companies c ON c.id=cy.company_id ORDER BY cy.id DESC")->fetchAll();}
 public function setCompanyStatus(int $id,string $status):bool{$s=$this->db->prepare("UPDATE companies SET status=? WHERE id=? AND status<>?");$s->execute([$status,$id,$status]);return$s->rowCount()===1;}
 public function globalSettings():array{return$this->db->query('SELECT setting_key,setting_value,updated_at FROM global_settings ORDER BY setting_key')->fetchAll();}
 public function saveSettings(array $values,int $userId):void{$s=$this->db->prepare('INSERT INTO global_settings(setting_key,setting_value,updated_by)VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($values as$key=>$value)$s->execute([$key,$value,$userId]);}
 public function schemaVersion():string{return(string)($this->db->query('SELECT migration FROM schema_migrations ORDER BY migration DESC LIMIT 1')->fetchColumn()?:'schema inicial');}
}
